from textlesson import build
S=dict(cls=6,subj="science",subj_file="science")
build(dict(S,ch="the-wonderful-world-of-science",topic="how-scientists-find-out",name_en="How scientists find things out",name_ta="அறிவியலாளர்கள் எப்படி கண்டறிகிறார்கள்",
 objectives=["Name the steps of a scientific investigation","Say why we change one thing at a time in a test"],
 story=("Which plant grows taller?","Nisha kept two bean seeds in two pots. One pot was in the sun and the other in a dark cupboard. She gave both the same water.\nAfter ten days the pot in the sun had a taller, green plant.\n\"Sunlight helps plants grow,\" she wrote in her notebook."),
 explain=["Science starts with curiosity: we notice something and ask a question, such as \"Does a plant need light?\"","We make a guess called a hypothesis, then test it with an experiment. In a fair test we change only one thing and keep everything else the same.","We observe and record what happens, using our senses and tools such as a ruler or thermometer, and write it in a notebook or a table.","From the records we draw a conclusion. If the result does not match our guess, that is fine. We learn from it and try again.","Scientists share what they find so that others can check it. Honesty and patience are important in science."],
 terms=["hypothesis","experiment","observation","conclusion","fair test"],
 narr=[("Science begins when we notice something and ask a question.","ask a question"),("We make a guess, then test it. In a fair test we change only one thing.","guess, test, change one thing"),("We observe and write down what happens. We must record honestly.","observe and record"),("Then we draw a conclusion and share it. If the guess was wrong, we learn and try again.","conclude and share")],
 ex=("Nisha tests whether plants need light. What should she keep the same in both pots?",[("She changes only one thing: the light.","A fair test changes one thing."),("So she keeps the water, soil, seed and pot size the same.","These could also affect growth."),("Then any difference in growth is because of light.","This makes the conclusion fair.")]),
 tb=("A friend tests two seeds, one in sun with lots of water and one in the dark with little water. Why is this not a fair test?",["More than one thing is different: light and water.","We cannot tell which one caused the change."],["Thinking you can change many things at once."]),
 summary=["Science starts with a question.","A fair test changes only one thing.","We record observations honestly and draw a conclusion."],
 q=[("mcq",1,"r1-start","Science usually starts with","a question",[("a holiday","Science starts from curiosity."),("a song","Science starts from curiosity.")],"We notice something and ask a question."),
    ("tf",1,"r1-note","Scientists record what they observe.",True,"True. Records help us check results."),
    ("mcq",2,"r2-guess","A guess that we can test is called a","hypothesis",[("conclusion","A conclusion comes after the test."),("observation","An observation is what we see.")],"A testable guess is a hypothesis."),
    ("tf",2,"r2-one","In a fair test we change many things at once.",False,"False. We change only one thing."),
    ("mcq",3,"r3-same","In a plant test about light, what should stay the same?","water and soil",[("the amount of light","Light is the thing we change."),("nothing","Other things must stay the same.")],"Everything except the tested thing stays the same."),
    ("short",3,"r3-tool","Name one tool used to measure in an experiment.",["ruler","thermometer","scale","measuring tape","stopwatch","balance"],"Tools such as a ruler or thermometer help us measure."),
    ("mcq",4,"r4-wrong","If the result does not match your guess, you should","learn from it and try again",[("hide the result","Honesty is important."),("change the record","Never change records.")],"A wrong guess still teaches us something."),
    ("tf",4,"r4-share","Scientists share their findings so others can check them.",True,"True.")]))
build(dict(S,ch="diversity-in-the-living-world",topic="grouping-living-things",name_en="Grouping living things",name_ta="உயிரினங்களைத் தொகுத்தல்",
 objectives=["Group living things by their features","Tell herbs, shrubs and trees apart"],
 story=("The sorting game","In the park Kiran counted twenty kinds of living things: a neem tree, a rose bush, grass, ants, a crow, a squirrel and a dog.\n\"How can I sort them?\" he asked.\nHis teacher said, \"Look at how they look and live. Group the ones that are alike.\""),
 explain=["There are millions of kinds of living things. We group them by similar features to understand them better. This is called classification.","Plants are grouped by size and stem. Herbs are small with a soft green stem. Shrubs are medium with several hard stems from the base. Trees are tall with one thick, hard trunk. Climbers and creepers need support or spread on the ground.","Animals are grouped too. Some have a backbone (fish, birds, reptiles, mammals) and some do not (insects, worms, snails).","Living things also live in different habitats: land, water, air, forests, deserts and mountains. Their body features help them live there. This is called adaptation.","Living things can be told apart from non-living things because they grow, need food and air, respond to their surroundings and reproduce."],
 terms=["classification","herb","shrub","tree","habitat","adaptation"],
 narr=[("We group living things that are alike. This is classification.","classification"),("Herbs are small, shrubs have many hard stems, and trees have one thick trunk.","herb, shrub, tree"),("Animals can have a backbone or not. A fish and a bird have one. An ant does not.","backbone / no backbone"),("A habitat is where a living thing lives. Its body suits that place, for example a fish has fins for water.","habitat and adaptation")],
 ex=("A plant is tall and has one thick, hard trunk. Is it a herb, a shrub or a tree?",[("Look at the stem: it is a thick, hard trunk.","The stem type tells the group."),("Herbs have soft stems and shrubs have many stems.","This plant has only one trunk."),("So it is a tree.","A tall plant with a single trunk is a tree.")]),
 tb=("A friend says a rose bush and a mango tree are the same kind of plant. How will you explain the difference?",["A rose bush is a shrub with many hard stems from the base.","A mango tree has one thick trunk and is much taller."],["Thinking all plants with leaves are the same group."]),
 summary=["We group living things by similar features.","Plants: herbs, shrubs, trees, climbers and creepers.","Habitat is where an organism lives and adaptation helps it live there."],
 q=[("mcq",1,"r1-tree","A tall plant with one thick trunk is a","tree",[("herb","Herbs are small with soft stems."),("shrub","Shrubs have many stems from the base.")],"Trees have a thick, hard trunk."),
    ("tf",1,"r1-grass","Grass is a herb.",True,"True. Grass has a small, soft stem."),
    ("mcq",2,"r2-back","Which animal has a backbone?","a fish",[("an ant","Ants have no backbone."),("an earthworm","Earthworms have no backbone.")],"Fish, birds, reptiles and mammals have a backbone."),
    ("tf",2,"r2-habitat","A habitat is the place where a living thing lives.",True,"True."),
    ("mcq",3,"r3-adapt","A fish has fins because it","lives in water",[("lives in a desert","Fins are for swimming."),("flies in air","Birds fly, not fish.")],"Its body suits its habitat."),
    ("short",3,"r3-group","What do we call grouping living things by features?",["classification","classifying"],"This is classification."),
    ("mcq",4,"r4-living","Which one shows that something is living?","it grows and responds",[("it is green","Some non-living things are green."),("it is big","Size does not decide life.")],"Living things grow, need food and respond."),
    ("tf",4,"r4-shrub","A shrub has one thick trunk.",False,"False. A shrub has many hard stems from the base.")]))
build(dict(S,ch="living-creatures-exploring-their-characteristics",topic="adaptations-of-animals",name_en="How animals suit their homes",name_ta="விலங்குகள் தம் வாழிடத்துக்கு ஏற்ப அமைதல்",
 objectives=["Explain how body features help an animal live in its habitat","Name animals of the desert, water and air"],
 story=("The camel's long walk","Jaya saw a camel walking steadily on hot sand. \"Why do its feet not sink?\" she asked.\n\"Its feet are wide and flat,\" said the guide, \"like snow shoes for sand. Camels also store fat in their humps for days without food.\""),
 explain=["Animals live in different places and their bodies suit these places. This is called adaptation.","Desert animals such as camels have wide flat feet for sand, long eyelashes against dust, and can go long without water.","Water animals such as fish have a streamlined body, fins to swim and gills to breathe in water. Ducks have webbed feet.","Birds have wings and light bodies with feathers to fly. Their hollow bones keep them light.","Animals in cold places, such as polar bears, have thick fur and a layer of fat to keep warm."],
 terms=["adaptation","gills","fins","feathers","habitat"],
 narr=[("Every animal's body suits its home. This is adaptation.","body suits home"),("A camel has wide feet for sand and can go long without water.","camel: desert"),("A fish has fins to swim and gills to breathe in water.","fish: fins and gills"),("A bird has wings and light feathers to fly. A polar bear has thick fur against the cold.","bird: fly, bear: warm")],
 ex=("Why does a duck have webbed feet?",[("A duck swims in water.","Its habitat is water."),("Webbed feet work like paddles and push water back.","They give a bigger surface to push."),("So webbed feet help it swim.","This is an adaptation to water.")]),
 tb=("Your friend asks why a polar bear does not feel cold. What will you say?",["It has thick fur and a layer of fat under the skin.","These adaptations keep its body warm."],["Thinking the animal does not feel cold because it is strong."]),
 summary=["Adaptation means body features that help living in a habitat.","Camels suit the desert; fish suit water; birds suit the air.","Polar animals have thick fur and fat to stay warm."],
 q=[("mcq",1,"r1-gills","How does a fish breathe in water?","with gills",[("with lungs like us","Fish use gills."),("through its ears","Fish use gills.")],"Fish take air from water with gills."),
    ("tf",1,"r1-camel","A camel can go long without water.",True,"True."),
    ("mcq",2,"r2-duck","Webbed feet help a duck to","swim",[("fly","Wings help it fly."),("climb","Webbed feet are for swimming.")],"They work like paddles."),
    ("tf",2,"r2-bones","Birds have heavy solid bones.",False,"False. Their bones are hollow and light."),
    ("mcq",3,"r3-bear","Which feature keeps a polar bear warm?","thick fur and fat",[("webbed feet","They help in swimming."),("long ears","Long ears do not keep it warm.")],"Fur and fat keep the cold out."),
    ("short",3,"r3-adapt","What do we call body features that suit an animal to its home?",["adaptation","adaptations"],"This is adaptation."),
    ("mcq",4,"r4-sand","Why does a camel have wide flat feet?","so it does not sink in sand",[("to swim","Camels do not swim."),("to fly","Camels cannot fly.")],"Wide feet spread its weight on sand."),
    ("tf",4,"r4-fins","Fins help a fish to swim.",True,"True.")]))
build(dict(S,ch="natures-treasures",topic="natural-resources",name_en="Natural resources",name_ta="இயற்கை வளங்கள்",
 objectives=["Name natural resources and their uses","Tell renewable and non-renewable resources apart"],
 story=("The village well","In Mala's village the well water was going down every summer.\nHer teacher said, \"Water, air, soil, forests and coal are gifts of nature. They are called natural resources.\"\n\"Then we must use them carefully,\" said Mala."),
 explain=["Things that nature gives us and that we use are natural resources. Air, water, soil, sunlight, forests, minerals and coal are examples.","Some resources renew themselves: sunlight, wind, water and forests (if we plant trees) are renewable. They are not used up easily.","Others took millions of years to form and will run out: coal, petroleum, natural gas and minerals are non-renewable. We must use them carefully.","We can protect resources by saving water and electricity, planting trees, reusing and recycling things, and not wasting food or fuel.","Solar energy and wind energy are clean renewable sources. They do not make smoke."],
 terms=["natural resource","renewable","non-renewable","recycle"],
 narr=[("Air, water, soil, forests, coal and sunlight come from nature. They are natural resources.","natural resources"),("Sunlight, wind and water can be used again and again. They are renewable.","renewable: sun, wind, water"),("Coal and petroleum took millions of years to form and will run out. They are non-renewable.","non-renewable: coal, petroleum"),("We can save resources by saving water, planting trees and recycling.","use carefully")],
 ex=("Is coal renewable or non-renewable? Give a reason.",[("Coal formed over millions of years from plants buried long ago.","It takes extremely long to form."),("We use it much faster than nature makes it.","So it will run out."),("So coal is non-renewable.","Such resources need careful use.")]),
 tb=("A friend says water cannot finish because it is everywhere. What will you tell him?",["Clean, usable water is limited, and wells and rivers can dry up.","We should save water and not waste it."],["Thinking all natural resources are unlimited."]),
 summary=["Natural resources come from nature.","Renewable resources are not used up easily; non-renewable ones will run out.","We should save, reuse and recycle."],
 q=[("mcq",1,"r1-sun","Which is a natural resource?","sunlight",[("a plastic toy","Toys are made by people."),("a cinema ticket","Tickets are made by people.")],"Sunlight comes from nature."),
    ("tf",1,"r1-air","Air is a natural resource.",True,"True."),
    ("mcq",2,"r2-renew","Which is a renewable resource?","wind",[("coal","Coal will run out."),("petroleum","Petroleum will run out.")],"Wind keeps blowing."),
    ("tf",2,"r2-coal","Coal is a non-renewable resource.",True,"True. It takes millions of years to form."),
    ("mcq",3,"r3-save","Which action saves natural resources?","closing a tap after use",[("leaving lights on","That wastes electricity."),("throwing food away","That wastes resources.")],"Closing the tap saves water."),
    ("short",3,"r3-example","Name one non-renewable resource.",["coal","petroleum","natural gas","minerals","petrol","diesel"],"Coal, petroleum and natural gas are non-renewable."),
    ("mcq",4,"r4-clean","Which energy source does not make smoke?","solar energy",[("burning coal","Coal makes smoke."),("burning wood","Wood makes smoke.")],"Solar energy is clean."),
    ("tf",4,"r4-recycle","Recycling helps save natural resources.",True,"True.")]))
build(dict(S,ch="measurement-of-length-and-motion",topic="types-of-motion",name_en="Types of motion",name_ta="இயக்கத்தின் வகைகள்",
 objectives=["Name rectilinear, circular, rotational, periodic and oscillatory motion","Give an example of each"],
 story=("The playground","At the playground Ali watched many things move: a ball rolling straight, a merry-go-round, a swing and a clock's pendulum.\n\"Do all move in the same way?\" he asked.\n\"No,\" said his teacher, \"there are different types of motion.\""),
 explain=["An object is in motion when its position changes with time. Things move in different ways.","Rectilinear motion is along a straight line, such as a car on a straight road. Circular motion is along a circle, such as a stone tied to a string and whirled around.","Rotational motion is spinning about a fixed axis, such as a top, a fan or the Earth. Oscillatory motion is a to-and-fro movement about a fixed point, such as a swing or a pendulum.","Periodic motion repeats after equal intervals of time, such as a pendulum, the Earth going around the Sun, or the second hand of a clock.","A motion can be of more than one type. A wheel of a moving bicycle both rotates and moves along a straight line."],
 terms=["rectilinear","circular","rotational","oscillatory","periodic"],
 narr=[("Something moves when its position changes with time.","position changes"),("A car on a straight road moves in a straight line. This is rectilinear motion.","straight line"),("A top spins about an axis. A swing goes to and fro. These are rotation and oscillation.","spin and to-and-fro"),("Motion that repeats after equal time is periodic, like a pendulum.","repeats: periodic")],
 ex=("What type of motion does a swing show?",[("A swing goes forward and backward again and again.","The movement is to and fro."),("It moves about a fixed point.","This is oscillation."),("So the swing shows oscillatory motion, which is also periodic.","It repeats after equal times.")]),
 tb=("Your friend says a spinning top has no motion because it stays at one place. How will you correct him?",["It spins about a fixed axis, which is rotational motion.","Motion does not always mean moving from one place to another."],["Thinking motion must change the place."]),
 summary=["Motion types: rectilinear, circular, rotational, oscillatory.","Periodic motion repeats after equal times.","One object can show more than one type of motion."],
 q=[("mcq",1,"r1-straight","A car moving on a straight road shows","rectilinear motion",[("circular motion","Circular is along a circle."),("oscillatory motion","Oscillatory is to and fro.")],"Straight-line motion is rectilinear."),
    ("tf",1,"r1-swing","A swing moves to and fro.",True,"True. This is oscillatory motion."),
    ("mcq",2,"r2-top","A spinning top shows","rotational motion",[("rectilinear motion","The top does not move in a straight line."),("no motion","It is clearly moving.")],"It spins about an axis."),
    ("tf",2,"r2-period","Periodic motion repeats after equal intervals of time.",True,"True."),
    ("mcq",3,"r3-circle","A stone whirled on a string shows","circular motion",[("rectilinear motion","It does not go in a straight line."),("rotational motion","It moves along a circle; it is circular motion.")],"It moves along a circle."),
    ("short",3,"r3-example","Name one thing that shows oscillatory motion.",["swing","pendulum","clock pendulum","guitar string"],"A swing or a pendulum goes to and fro."),
    ("mcq",4,"r4-wheel","A bicycle wheel on a straight road shows","rotation and straight-line motion",[("only oscillation","It does not go to and fro."),("no motion","It is clearly moving.")],"It spins and also moves forward."),
    ("tf",4,"r4-place","An object must change its place to be in motion.",False,"False. A spinning top is in motion at one place.")]))
